        { root: ['./src'], alias: { '@': './src' } }, // import { Button } from '@/ui/Button'
      ],
    ],
  };
};

import { fileURLToPath, URL } from 'node:url';
import react from '@vitejs/plugin-react';
import { defineConfig } from 'vite';

export default defineConfig({
  plugins: [react()],
  resolve: {
    alias: { '@': fileURLToPath(new URL('./src', import.meta.url)) },
  },
  server: {
    // Em desenvolvimento, /api/* vai para o backend local: sem CORS no navegador
    proxy: { '/api': { target: 'http://localhost:3000', changeOrigin: true } },
  },
  build: {
    sourcemap: 'hidden', // gera os .map para o monitoramento de erros, sem link no bundle
  },
});

import { lazy, Suspense } from 'react';
import { Route, Routes } from 'react-router';

// Cada import() vira um chunk separado, baixado só quando a rota abre
const Orders = lazy(() => import('./pages/Orders'));
const Reports = lazy(() => import('./pages/Reports')); // gráficos pesados ficam fora do bundle inicial

export function AppRoutes() {
  return (
    <Suspense fallback={<p>Carregando…</p>}>
      <Routes>
        <Route path="/pedidos" element={<Orders />} />
        <Route path="/relatorios" element={<Reports />} />
      </Routes>
    </Suspense>
  );
}

const { getDefaultConfig } = require('expo/metro-config');

const config = getDefaultConfig(__dirname); // parte sempre da config padrão do Expo

// .svg deixa de ser asset (imagem) e passa a ser código, transformado em componente
config.transformer.babelTransformerPath = require.resolve('react-native-svg-transformer/expo');
config.resolver.assetExts = config.resolver.assetExts.filter((ext) => ext !== 'svg');
config.resolver.sourceExts.push('svg');

module.exports = config;
